-- Isolated contract fixture derived from read-only production introspection.
create extension if not exists pgcrypto;
create role anon nologin;
create role authenticated nologin;
create role service_role nologin;
create schema auth;
create table auth.users (id uuid primary key);
create type public.orbit_role as enum ('CEO', 'ADMINISTRATOR', 'READONLY');

create table public.profiles (
  id uuid primary key,
  role public.orbit_role not null default 'READONLY',
  display_name text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table public.projects (
  id uuid primary key default gen_random_uuid(),
  customer_id uuid not null,
  orbit_event_id text not null,
  name text not null,
  project_type text not null,
  status text not null,
  health text not null,
  event_date date,
  event_time time default '22:00:00',
  location text,
  city text,
  budget jsonb not null default '{}'::jsonb,
  contract jsonb not null default '{}'::jsonb,
  finance jsonb not null default '{}'::jsonb,
  operations jsonb not null default '{}'::jsonb,
  resources jsonb not null default '{}'::jsonb,
  version integer not null default 1,
  created_by uuid,
  created_at timestamptz not null default now(),
  updated_by uuid
);
create table public.audit_events (
  id bigint generated by default as identity primary key,
  entity_type text not null,
  entity_id text not null,
  action text not null,
  actor_id uuid,
  reason text,
  previous_state jsonb,
  new_state jsonb,
  orbit_event_id text,
  occurred_at timestamptz not null default now()
);
create index audit_events_entity_type_occurred_at_idx on public.audit_events (entity_type, occurred_at desc);
create index audit_events_staff_entity_time_idx on public.audit_events (occurred_at desc, entity_id) where entity_type = 'staff';

create table public.calendar_sync (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects(id) on delete cascade,
  orbit_event_id text not null,
  external_event_id text unique,
  external_url text,
  status text not null,
  last_synced_at timestamptz,
  payload_hash text,
  version integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  last_error jsonb,
  legacy_external_event_id text,
  legacy_external_url text,
  nova_external_event_id text,
  nova_external_url text,
  nova_calendar_id text,
  nova_migration_status text check (nova_migration_status is null or nova_migration_status in ('PENDING','MIGRATED','SKIPPED_DELETED','ERROR')),
  nova_migrated_at timestamptz,
  nova_migration_error jsonb,
  current_payload_hash text,
  last_synced_payload_hash text,
  retry_count integer not null default 0,
  next_retry_at timestamptz,
  sync_started_at timestamptz,
  last_error_code text,
  current_event_revision bigint,
  last_synced_event_revision bigint,
  approved_remote_payload_hash text,
  approved_remote_source_hash text,
  approved_remote_etag text,
  approved_remote_snapshot jsonb,
  approved_remote_at timestamptz,
  approved_remote_by uuid references auth.users(id),
  constraint calendar_sync_orbit_event_id_key unique (orbit_event_id),
  constraint calendar_sync_project_id_key unique (project_id)
);
create unique index calendar_sync_nova_external_event_id_uidx on public.calendar_sync (nova_external_event_id) where nova_external_event_id is not null;
create index calendar_sync_resync_queue_idx on public.calendar_sync (status, next_retry_at, sync_started_at) where status in ('PENDING','STALE','FAILED','SYNCING');

create or replace function auth.uid() returns uuid language sql stable security definer set search_path = pg_catalog, public
as $$ select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;
create or replace function public.current_orbit_role() returns public.orbit_role language sql stable security definer set search_path = public
as $$ select role from public.profiles where id = auth.uid() $$;
create or replace function public.can_administer() returns boolean language sql stable security definer set search_path = public
as $$ select auth.uid() is not null and public.current_orbit_role() in ('CEO','ADMINISTRATOR') $$;
create or replace function public.is_internal_user() returns boolean language sql stable security definer set search_path = public
as $$ select auth.uid() is not null and public.current_orbit_role() in ('CEO','ADMINISTRATOR','READONLY') $$;
create or replace function public.touch_versioned_row() returns trigger language plpgsql security definer set search_path = public, pg_temp
as $$ begin new.updated_at = now(); new.version = old.version + 1; return new; end $$;
create or replace function public.audit_row_change() returns trigger language plpgsql security definer set search_path = public, pg_temp
as $$
begin
  insert into public.audit_events(entity_type, entity_id, action, actor_id, previous_state, new_state, orbit_event_id)
  values (tg_table_name, coalesce((new).id, (old).id)::text, tg_op, auth.uid(), to_jsonb(old), to_jsonb(new), coalesce((new).orbit_event_id, (old).orbit_event_id));
  return coalesce(new, old);
end
$$;
create trigger calendar_sync_audit after insert or delete or update on public.calendar_sync for each row execute function public.audit_row_change();
create trigger calendar_sync_touch before update on public.calendar_sync for each row execute function public.touch_versioned_row();

alter table public.profiles enable row level security;
alter table public.calendar_sync enable row level security;
alter table public.audit_events enable row level security;
create policy profiles_admin_write on public.profiles for all to public using (can_administer()) with check (can_administer());
create policy profiles_self_read on public.profiles for select to authenticated using (id = auth.uid() or is_internal_user());
create policy calendar_sync_admin_write on public.calendar_sync for all to public using (can_administer()) with check (can_administer());
create policy calendar_sync_internal_read on public.calendar_sync for select to public using (is_internal_user());
create policy audit_events_admin_write on public.audit_events for all to authenticated using (can_administer()) with check (can_administer());
create policy audit_events_internal_read on public.audit_events for select to authenticated using (is_internal_user());
grant usage on schema public, auth to anon, authenticated, service_role;
grant select on public.profiles, public.calendar_sync, public.audit_events, public.projects to authenticated, service_role;
grant execute on function auth.uid(), public.current_orbit_role(), public.can_administer(), public.is_internal_user() to authenticated, service_role;
